package com.zxl.zxlaiagent.security;
import org.junit.jupiter.api.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
class AuthorizationDecisionTest extends AuthenticationPgTest {
 AuthorizationService policy; ActorRef ref;
 @BeforeEach void policy(){policy=new AuthorizationService(db);ref=auth.login(subject,"synthetic-password",tenant).actor().ref();}
  @Test void malformedAuthorityInputsFailClosed(){assertThrows(SecurityFailure.class,()->policy.decide(null,"knowledge.read",ResourceRef.tenant(),Phase.ENTRY,null));var tickets=new ServiceCallAuthorizer(db,policy);assertThrows(SecurityFailure.class,()->tickets.issue(ref,"worker","knowledge.read",ResourceRef.tenant(),null));assertThrows(SecurityFailure.class,()->tickets.issue(ref,"worker","knowledge.read",ResourceRef.tenant(),"a".repeat(64),null));assertThrows(SecurityFailure.class,()->tickets.consume(null,"worker","knowledge.read",null));}
 @Test void decisionAuditUsesActualVersionAndPhase(){var first=policy.decide(ref,"knowledge.read",ResourceRef.tenant(),Phase.TOOL_DISPATCH,"run");assertTrue(first.allowed());policy.setMembershipActive(ref,false);var denied=policy.decide(ref,"knowledge.read",ResourceRef.tenant(),Phase.PUBLISH,"run");assertFalse(denied.allowed());assertNotEquals(first.version(),denied.version());db.tx(c->{try(var s=SecurityDatabase.statement(c,"SELECT version,phase,allowed FROM authorization_audit WHERE decision_id=?",denied.decisionId());var r=s.executeQuery()){assertTrue(r.next());assertEquals(denied.version(),r.getString(1));assertEquals("PUBLISH",r.getString(2));assertFalse(r.getBoolean(3));}return null;});}
 @Test void unknownActionsAndOwnersFailClosed(){assertFalse(policy.decide(ref,"unknown",ResourceRef.tenant(),Phase.ENTRY,null).allowed());assertFalse(policy.decide(ref,"knowledge.manage",ResourceRef.tenant(),Phase.ENTRY,null).allowed());policy.registerResource(ref,new ResourceRef("conversation","test-"+subject));assertTrue(policy.decide(ref,"conversation.readOwn",new ResourceRef("conversation","test-"+subject),Phase.HISTORY_READ,null).allowed());assertFalse(policy.decide(ref,"conversation.readOwn",new ResourceRef("conversation","missing"),Phase.HISTORY_READ,null).allowed());}
 @Test void revocationWaitsForGateAndNextActionIsDenied()throws Exception{var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var call=pool.submit(()->policy.gate(ref,"knowledge.read",ResourceRef.tenant(),Phase.TOOL_DISPATCH,null,()->{entered.countDown();try{release.await(2,TimeUnit.SECONDS);}catch(InterruptedException e){throw new RuntimeException(e);}return "started";}));assertTrue(entered.await(2,TimeUnit.SECONDS));var revoke=pool.submit(()->policy.setMembershipActive(ref,false));Thread.sleep(100);assertFalse(revoke.isDone());release.countDown();assertEquals("started",call.get());revoke.get();assertThrows(SecurityFailure.class,()->policy.gate(ref,"knowledge.read",ResourceRef.tenant(),Phase.MODEL_DISPATCH,null,()->"must not execute"));}finally{release.countDown();pool.shutdownNow();}}
  @Test void multiSubjectDecisionsAndOwnershipNeverMix(){String other=subject+"-other";auth.provision(other,other,"synthetic-password",tenant,"knowledge-maintainer");try{var another=auth.login(other,"synthetic-password",tenant).actor().ref();var resource=new ResourceRef("conversation",subject+"-private");policy.registerResource(ref,resource);assertFalse(policy.decide(another,"conversation.readOwn",resource,Phase.HISTORY_READ,null).allowed());policy.setMembershipActive(ref,false);assertTrue(policy.decide(another,"knowledge.manage",ResourceRef.tenant(),Phase.ENTRY,null).allowed());policy.setMembershipActive(ref,true);var restored=policy.decide(ref,"knowledge.read",ResourceRef.tenant(),Phase.PUBLISH,null);assertTrue(restored.allowed());assertTrue(restored.version().startsWith("epoch:3;"));}finally{db.tx(c->{try(var st=SecurityDatabase.statement(c,"DELETE FROM authorization_audit WHERE subject_id=?",other)){st.executeUpdate();}try(var st=SecurityDatabase.statement(c,"DELETE FROM subject WHERE subject_id=?",other)){st.executeUpdate();}return null;});}}
 @Test void expiryFingerprintAndConcurrentReplayAreRejected()throws Exception{var tickets=new ServiceCallAuthorizer(db,policy);String hash=ServiceCallAuthorizer.requestHash("POST","/retrieval",new byte[]{1});String ticket=tickets.issue(ref,"worker","knowledge.read",ResourceRef.tenant(),hash);assertThrows(SecurityFailure.class,()->tickets.consume(ticket,"worker","knowledge.read",ServiceCallAuthorizer.requestHash("POST","/retrieval",new byte[]{2})));var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{try{tickets.consume(ticket,"worker","knowledge.read",hash);return 1;}catch(SecurityFailure e){return 0;}});var b=pool.submit(()->{try{tickets.consume(ticket,"worker","knowledge.read",hash);return 1;}catch(SecurityFailure e){return 0;}});assertEquals(1,a.get()+b.get());}finally{pool.shutdownNow();}String expired=tickets.issue(ref,"worker","knowledge.read",ResourceRef.tenant(),hash,java.time.Duration.ofMillis(1));Thread.sleep(10);assertThrows(SecurityFailure.class,()->tickets.consume(expired,"worker","knowledge.read",hash));}
 @Test void ticketsAreBoundAndOneTimeAndRecheckPermissions(){var tickets=new ServiceCallAuthorizer(db,policy);String hash=ServiceCallAuthorizer.requestHash("GET","/documents",new byte[0]);String ticket=tickets.issue(ref,"knowledge-worker","knowledge.read",ResourceRef.tenant(),hash);assertThrows(SecurityFailure.class,()->tickets.consume(ticket,"mcp", "knowledge.read",hash));assertEquals(ref,tickets.consume(ticket,"knowledge-worker","knowledge.read",hash));assertThrows(SecurityFailure.class,()->tickets.consume(ticket,"knowledge-worker","knowledge.read",hash));String late=tickets.issue(ref,"knowledge-worker","knowledge.read",ResourceRef.tenant(),hash);policy.setMembershipActive(ref,false);assertThrows(SecurityFailure.class,()->tickets.consume(late,"knowledge-worker","knowledge.read",hash));}
}
